+	if (unlikely(child == &noop_qdisc))
 		return NULL;

 	if (TXTIME_ASSIST_IS_ENABLED(q->flags))
 		goto skip_peek_checks;

 	skb = child->ops->peek(child);
 	if (!skb)
 		return NULL;

 	prio = skb->priority;
 	tc = netdev_get_prio_tc_map(dev, prio);

